import { writeFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import tokens from '../design/tokens.json';

type Tokens = typeof tokens;

export function generateCss(t: Tokens): string {
  const lines: string[] = [
    '/* GENERATED by scripts/tokens-to-css.ts from design/tokens.json. Do not edit. */',
    ':root {',
  ];
  for (const [name, c] of Object.entries(t.color)) lines.push(`  --${name}: ${c.value};`);
  lines.push(`  --font-display: ${t.font.display.default};`);
  lines.push(`  --font-body: ${t.font.body.default};`);
  for (const [name, v] of Object.entries(t.radius)) lines.push(`  --radius-${name}: ${v};`);
  for (const [name, v] of Object.entries(t.space)) lines.push(`  --space-${name}: ${v};`);
  for (const [name, v] of Object.entries(t.motion)) lines.push(`  --${name}: ${v};`);
  lines.push('}');
  for (const [lang, f] of Object.entries(t.font.lang)) {
    lines.push('', `:lang(${lang}) {`, `  --font-display: ${f.display};`, `  --font-body: ${f.body};`, '}');
  }
  return lines.join('\n') + '\n';
}

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  writeFileSync('src/styles/tokens.css', generateCss(tokens));
  console.log('wrote src/styles/tokens.css');
}
